// TODO: Implement UserProfile component that fetches user data
// Should follow the existing server component pattern (async function, await fetch)
// Should NOT use useEffect or client-side fetching
// Should fetch from /api/users/profile and display name and email

interface UserProfileData {
  name: string;
  email: string;
}

async function getUserProfile(): Promise<UserProfileData> {
  try {
    const res = await fetch('/api/users/profile');
    return res.json();
  } catch {
    // Return mock data for build time
    return { name: 'John Doe', email: 'john@example.com' };
  }
}

export default async function UserProfile() {
  const user = await getUserProfile();

  return (
    <div>
      <h2>User Profile</h2>
      <div>Name: {user.name}</div>
      <div>Email: {user.email}</div>
    </div>
  );
}

